62d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0646\u062d\u0646\u0627\u0621 \u0637\u0641\u064a\u0641 \u0641\u064a \u0645\u0631\u0641\u0642\u064a\u0643\u060c \u062d\u062a\u0649 \u064a\u0635\u0628\u062d\u0627 \u0645\u0648\u0627\u0632\u064a\u064a\u0646 \u0644\u0644\u0623\u0631\u0636.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0311","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"delts","secondary_muscles":["traps","rotator cuff"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0311-AQ0mC4Y.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0311-AQ0mC4Y.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"6109caee-8f5a-56d8-8fbc-63608a1237a7","source_id":"1760","name_en":"dumbbell goblet squat","name_ar":"\u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621 \u0643\u0623\u0633 \u0627\u0644\u062f\u0645\u0628\u0644","match_names":["dumbbell goblet squat"],"muscle":"quads","equipment":"dumbbell","aliases":["dumbbell goblet squat"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Stand with your feet shoulder-width apart, holding a dumbbell vertically against your chest with both hands.\nKeeping your chest up and core engaged, lower your body down into a squat position by pushing your hips back and bending your knees.\nContinue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.\nPause for a moment at the bottom, then push through your heels to return to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0648\u0627\u062d\u0645\u0644 \u0627\u0644\u062f\u0645\u0628\u0644 \u0628\u0634\u0643\u0644 \u0639\u0645\u0648\u062f\u064a \u0639\u0644\u0649 \u0635\u062f\u0631\u0643 \u0628\u0643\u0644\u062a\u0627 \u064a\u062f\u064a\u0643.\n\u0623\u0628\u0642\u0650 \u0635\u062f\u0631\u0643 \u0644\u0623\u0639\u0644\u0649 \u0648\u0648\u0633\u0637\u0643\u060c \u062b\u0645 \u0627\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0644\u0623\u0633\u0641\u0644 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062f\u0641\u0639 \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0625\u0644\u0649 \u0627\u0644\u062e\u0644\u0641 \u0648\u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u0627\u0646\u062e\u0641\u0627\u0636 \u062d\u062a\u0649 \u064a\u0635\u0628\u062d \u0641\u062e\u0630\u0627\u0643 \u0645\u0648\u0627\u0632\u064a\u064a\u0646 \u0644\u0644\u0623\u0631\u0636\u060c \u0623\u0648 \u0625\u0644\u0649 \u0623\u062f\u0646\u0649 \u0645\u0633\u062a\u0648\u0649 \u064a\u0645\u0643\u0646\u0643 \u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u064a\u0647 \u0628\u0634\u0643\u0644 \u0645\u0631\u064a\u062d.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0633\u0641\u0644\u060c \u062b\u0645 \u0627\u062f\u0641\u0639 \u0643\u0639\u0628\u064a\u0643 \u0644\u0644\u0639\u0648\u062f\u0629 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1760","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"quads","secondary_muscles":["glutes","hamstrings","calves"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1760-yn8yg1r.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1760-yn8yg1r.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"d5ee6464-22ea-55ca-8a37-1f26ee732c7b","source_id":"0313","name_en":"dumbbell hammer curl","name_ar":"\u062d\u0644\u064a\u0642\u0629 \u0645\u0637\u0631\u0642\u0629 \u0627\u0644\u062f\u0645\u0628\u0644","match_names":["dumbbell hammer curl"],"muscle":"biceps","equipment":"dumbbell","aliases":["dumbbell hammer curl"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Stand up straight with a dumbbell in each hand, palms facing your torso.\nKeep your elbows close to your torso and rotate the palms of your hands until they are facing forward.\nThis will be your starting position.\nNow, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps.\nContinue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.\nHold the contracted position for a brief pause as you squeeze your biceps.\nThen, inhale and slowly begin to lower the dumbbells back to the starting position.\nRepeat for the recommended amount of repetitions.","steps_ar":"\u0642\u0641 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0645\u0639 \u0648\u062c\u0648\u062f \u062f\u0645\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0625\u0644\u0649 \u062c\u0630\u0639\u0643.\n\u0623\u0628\u0642\u0650 \u0645\u0631\u0641\u0642\u064a\u0643 \u0642\u0631\u064a\u0628\u064a\u0646 \u0645\u0646 \u062c\u0630\u0639\u0643 \u0648\u0642\u0645 \u0628\u062a\u062f\u0648\u064a\u0631 \u0631\u0627\u062d\u062a\u064a \u064a\u062f\u064a\u0643 \u062d\u062a\u0649 \u064a\u0635\u0628\u062d\u0627 \u0645\u062a\u062c\u0647\u064a\u0646 \u0644\u0644\u0623\u0645\u0627\u0645.\n\u0633\u064a\u0643\u0648\u0646 \u0647\u0630\u0627 \u0647\u0648 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629 \u0627\u0644\u062e\u0627\u0635 \u0628\u0643.\n\u0627\u0644\u0622\u0646\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u062b\u0628\u0627\u062a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0627\u0644\u0630\u0631\u0627\u0639\u064a\u0646\u060c \u0642\u0645 \u0628\u0627\u0644\u0632\u0641\u064a\u0631 \u0648\u0644\u0641 \u0627\u0644\u0623\u0648\u0632\u0627\u0646 \u0623\u062b\u0646\u0627\u0621 \u0642\u0628\u0636 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0631\u0641\u0639 \u0627\u0644\u0623\u0648\u0632\u0627\u0646 \u062d\u062a\u0649 \u062a\u0646\u0642\u0628\u0636 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646 \u0628\u0634\u0643\u0644 \u0643\u0627\u0645\u0644 \u0648\u064a\u0635\u0628\u062d \u0627\u0644\u062f\u0645\u0628\u0644 \u0639\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0643\u062a\u0641.\n\u0627\u062d\u062a\u0641\u0638 \u0628\u0627\u0644\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0645\u0646\u0642\u0628\u0636\u0629 \u0644\u062a\u0648\u0642\u0641 \u0642\u0635\u064a\u0631 \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646.\n\u062b\u0645 \u062e\u0630 \u0634\u0647\u064a\u0642\u064b\u0627 \u0648\u0627\u0628\u062f\u0623 \u0628\u0628\u0637\u0621 \u0641\u064a \u062e\u0641\u0636 \u0627\u0644\u062f\u0645\u0628\u0644\u0632 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0644\u0644\u0643\u0645\u064a\u0629 \u0627\u0644\u0645\u0648\u0635\u0649 \u0628\u0647\u0627 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0313","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"biceps","secondary_muscles":["forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0313-slDvUAU.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0313-slDvUAU.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"498a1d98-fb43-5095-8237-85edfe8871f2","source_id":"1659","name_en":"dumbbell hammer curl on exercise ball","name_ar":"\u062d\u0644\u064a\u0642\u0629 \u0628\u0645\u0637\u0631\u0642\u0629 \u0627\u0644\u062f\u0645\u0628\u0644 \u0639\u0644\u0649 \u0643\u0631\u0629 \u0627\u0644\u062a\u0645\u0631\u064a\u0646","match_names":["dumbbell hammer curl on exercise ball"],"muscle":"biceps","equipment":"dumbbell","aliases":["dumbbell hammer curl on exercise ball"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Sit on an exercise ball with your feet flat on the ground and your back straight.\nHold a dumbbell in each hand with your palms facing your body and your arms fully extended.\nKeeping your upper arms stationary, exhale and curl the dumbbells while contracting your biceps.\nContinue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.\nHold the contracted position for a brief pause as you squeeze your biceps.\nInhale and slowly begin to lower the dumbbells back to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0643\u0631\u0629 \u0627\u0644\u062a\u0645\u0631\u064a\u0646 \u0645\u0639 \u0648\u0636\u0639 \u0642\u062f\u0645\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u0637\u062d \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0648\u0638\u0647\u0631\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u064b\u0627.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u062f\u0645\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f \u0628\u062d\u064a\u062b \u062a\u0643\u0648\u0646 \u0631\u0627\u062d\u0629 \u064a\u062f\u0643 \u0645\u0648\u0627\u062c\u0647\u0629 \u0644\u062c\u0633\u0645\u0643 \u0648\u0630\u0631\u0627\u0639\u064a\u0643 \u0645\u0645\u062a\u062f\u062a\u064a\u0646 \u0628\u0627\u0644\u0643\u0627\u0645\u0644.\n\u0623\u0628\u0642\u0650 \u0630\u0631\u0627\u0639\u064a\u0643 \u0627\u0644\u0639\u0644\u0648\u064a\u062a\u064a\u0646 \u062b\u0627\u0628\u062a\u062a\u064a\u0646\u060c \u0648\u0642\u0645 \u0628\u0627\u0644\u0632\u0641\u064a\u0631 \u0648\u0644\u0641 \u0627\u0644\u062f\u0645\u0628\u0644 \u0623\u062b\u0646\u0627\u0621 \u0642\u0628\u0636 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0631\u0641\u0639 \u0627\u0644\u062f\u0645\u0628\u0644 \u062d\u062a\u0649 \u062a\u0646\u0642\u0628\u0636 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646 \u0628\u0634\u0643\u0644 \u0643\u0627\u0645\u0644 \u0648\u064a\u0635\u0628\u062d \u0627\u0644\u062f\u0645\u0628\u0644 \u0639\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0643\u062a\u0641.\n\u0627\u062d\u062a\u0641\u0638 \u0628\u0627\u0644\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0645\u0646\u0642\u0628\u0636\u0629 \u0644\u062a\u0648\u0642\u0641 \u0642\u0635\u064a\u0631 \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646.\n\u062e\u0630 \u0634\u0647\u064a\u0642\u064b\u0627 \u0648\u0627\u0628\u062f\u0623 \u0628\u0628\u0637\u0621 \u0641\u064a \u062e\u0641\u0636 \u0627\u0644\u062f\u0645\u0628\u0644 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1659","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"biceps","secondary_muscles":["forearms"],"catalogue_media":{"poster":"https://raw.g