on":"per_hand","guidance":{"steps_en":"Sit on an incline bench with a dumbbell in one hand, resting it on your thigh.\nLean forward and position your upper arm against the inside of your thigh.\nRaise the dumbbell to the side, keeping your arm slightly bent and your palm facing down.\nContinue lifting until your arm is parallel to the floor.\nPause for a moment at the top, then slowly lower the dumbbell back to the starting position.\nRepeat for the desired number of repetitions, then switch to the other arm.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0645\u0642\u0639\u062f \u0645\u0627\u0626\u0644 \u0645\u0639 \u062d\u0645\u0644 \u0627\u0644\u062f\u0645\u0628\u0644 \u0641\u064a \u0625\u062d\u062f\u0649 \u064a\u062f\u064a\u0643\u060c \u062b\u0645 \u0636\u0639\u0647 \u0639\u0644\u0649 \u0641\u062e\u0630\u0643.\n\u0627\u0646\u062d\u0646 \u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0627\u0645 \u0648\u0636\u0639 \u0630\u0631\u0627\u0639\u0643 \u0627\u0644\u0639\u0644\u0648\u064a \u0639\u0644\u0649 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u062f\u0627\u062e\u0644\u064a \u0645\u0646 \u0641\u062e\u0630\u0643.\n\u0627\u0631\u0641\u0639 \u0627\u0644\u062f\u0645\u0628\u0644 \u0625\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0630\u0631\u0627\u0639\u0643 \u0645\u062b\u0646\u064a\u064b\u0627 \u0642\u0644\u064a\u0644\u0627\u064b \u0648\u0631\u0627\u062d\u0629 \u064a\u062f\u0643 \u0645\u062a\u062c\u0647\u0629 \u0644\u0644\u0623\u0633\u0641\u0644.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u0631\u0641\u0639 \u062d\u062a\u0649 \u064a\u0635\u0628\u062d \u0630\u0631\u0627\u0639\u0643 \u0645\u0648\u0627\u0632\u064a\u064b\u0627 \u0644\u0644\u0623\u0631\u0636\u064a\u0629.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0627\u0644\u062f\u0645\u0628\u0644 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0630\u0644\u0643 \u0628\u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a\u060c \u062b\u0645 \u0627\u0646\u062a\u0642\u0644 \u0625\u0644\u0649 \u0627\u0644\u0630\u0631\u0627\u0639 \u0627\u0644\u0623\u062e\u0631\u0649.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0323","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"delts","secondary_muscles":["trapezius","triceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0323-aTNKZiC.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0323-aTNKZiC.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"0763b8a9-97d4-592b-8a1b-b285ec07dbb7","source_id":"1281","name_en":"dumbbell incline one arm press","name_ar":"\u0627\u0644\u0636\u063a\u0637 \u0628\u0627\u0644\u062f\u0645\u0628\u0644 \u0639\u0644\u0649 \u0630\u0631\u0627\u0639 \u0648\u0627\u062d\u062f\u0629","match_names":["dumbbell incline one arm press"],"muscle":"chest","equipment":"dumbbell","aliases":["dumbbell incline one arm press"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Sit on an incline bench with a dumbbell in one hand, resting on your thigh.\nLie back on the bench and position the dumbbell at shoulder level, palm facing forward.\nPress the dumbbell upward and slightly inward, extending your arm fully.\nPause for a moment at the top, then slowly lower the dumbbell back to the starting position.\nRepeat for the desired number of repetitions, then switch to the other arm.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0645\u0642\u0639\u062f \u0645\u0627\u0626\u0644 \u0645\u0639 \u062d\u0645\u0644 \u0627\u0644\u062f\u0645\u0628\u0644 \u0641\u064a \u0625\u062d\u062f\u0649 \u064a\u062f\u064a\u0643\u060c \u0648\u0627\u0633\u062a\u0631\u064a\u062d \u0639\u0644\u0649 \u0641\u062e\u0630\u0643.\n\u0627\u0633\u062a\u0644\u0642\u0650 \u0639\u0644\u0649 \u0627\u0644\u0645\u0642\u0639\u062f\u060c \u0648\u0636\u0639 \u0627\u0644\u062f\u0645\u0628\u0644 \u0639\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0643\u062a\u0641\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u0629 \u0627\u0644\u064a\u062f \u0644\u0644\u0623\u0645\u0627\u0645.\n\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u062f\u0645\u0628\u0644 \u0644\u0644\u0623\u0639\u0644\u0649 \u0648\u0644\u0644\u062f\u0627\u062e\u0644 \u0642\u0644\u064a\u0644\u0627\u064b\u060c \u0645\u0639 \u0645\u062f \u0630\u0631\u0627\u0639\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0627\u0644\u062f\u0645\u0628\u0644 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0630\u0644\u0643 \u0628\u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a\u060c \u062b\u0645 \u0627\u0646\u062a\u0642\u0644 \u0625\u0644\u0649 \u0627\u0644\u0630\u0631\u0627\u0639 \u0627\u0644\u0623\u062e\u0631\u0649.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1281","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"pectorals","secondary_muscles":["shoulders","triceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1281-rDAiRf9.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1281-rDAiRf9.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"68e0d6b5-0094-521d-80bf-54165e4e36e2","source_id":"1282","name_en":"dumbbell incline one arm press on exercise ball","name_ar":"\u0627\u0644\u062f\u0645\u0628\u0644 \u0645\u0627\u0626\u0644\u060c \u0627\u0636\u063a\u0637 \u0628\u0630\u0631\u0627\u0639 \u0648\u0627\u062d\u062f\u0629 \u0639\u0644\u0649 \u0643\u0631\u0629 \u0627\u0644\u062a\u0645\u0631\u064a\u0646","match_names":["dumbbell incline one arm press on exercise ball"],"muscle":"chest","equipment":"dumbbell","aliases":["dumbbell incline one arm press on exercise ball"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Sit on an exercise ball with a dumbbell in one hand, feet flat on the ground.\nSlowly walk your feet forward, rolling the ball until your head, neck, and upper back are supported on the ball.\nHold the dumbbell at shoulder height with your palm facing forward.\nPress the dumbbell upward until your arm is fully extended.\nPause for a moment at the top, then slowly lower the dumbbell back to the starting position.\nRepeat for the desired number of repetitions, then switch to the other arm.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0643\u0631\u0629 \u0627\u0644\u062a\u0645\u0631\u064a\u0646 \u0645\u0639 \u062d\u0645\u0644 \u0627\u0644\u062f\u0645\u0628\u0644 \u0641\u064a \u0625\u062d\u062f\u0649 \u064a\u062f\u064a\u0643\u060c \u0645\u0639 \u0648\u0636\u0639 \u0627\u0644\u0642\u062f\u0645\u064a\u0646 \u0628\u0634\u0643\u0644 \u0645\u0633\u0637\u062d \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0642\u0645 \u0628\u0627\u0644\u0645\u0634\u064a \u0628\u0628\u0637\u0621 \u0628\u0642\u062f\u0645\u064a\u0643 \u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0627\u0645\u060c \u0648\u062f\u062d\u0631\u062c\u0629 \u0627\u0644\u0643\u0631\u0629 \u062d\u062a\u0649 \u064a\u062a\u0645 \u062f\u0639\u0645 \u0631\u0623\u0633\u0643 \u0648\u0631\u0642\u0628\u062a\u0643 \u0648\u0623\u0639\u0644\u0649 \u0638\u0647\u0631\u0643 \u0639\u0644\u0649 \u0627\u0644\u0643\u0631\u0629.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u062f\u0645\u0628\u0644 \u0639\u0644\u0649 \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0643\u062a\u0641 \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u0629 \u064a\u062f\u0643 \u0644\u0644\u0623\u0645\u0627\u0645.\n\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u062f\u0645\u0628\u0644 \u0644\u0623\u0639\u0644\u0649 \u062d\u062a\u0649 \u064a\u062a\u0645 \u062a\u0645\u062f\u064a\u062f \u0630\u0631\u0627\u0639\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0627\u0644\u062f\u0645\u0628\u0644 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0630\u0644\u0643 \u0628\u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a\u060c \u062b\u0645 \u0627\u0646\u062a\u0642\u0644 \u0625\u0644\u0649 \u0627\u0644\u0630\u0631\u0627\u0639 \u0627\u0644\u0623\u062e\u0631\u0649.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1282","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"pectorals","secondary_muscles":["shoulders","triceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1282-Bg5JKSH.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1282-Bg5JKSH.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"385eb6e3-a5f7-5660-8d78-22474532cda4","source_id":"0324","name_en":"dumbbell incline palm-in press","name_ar":"\u0627\u0644\u0636\u063a\u0637 \u0628\u0627\u0644\u062f\u0645\u0628\u0644 \u0645\u0639 \u0631\u0627\u062d\u0629 \u0627\u0644\u064a\u062f","match_names":["dumbbell incline palm-in press"],"muscle":"chest","equipment":"dumbbell","aliases":["dumbbell incline palm-in press"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Set up an incline bench at a 45-degree angle.\nSit on the bench with a dumbbell in each hand, palms facing each other.\nPlant your feet firmly on the ground and keep your back straight against the bench.\nStart with the dumbbells at shoulder level, elbows bent and palms facing each other.\nPress the dumbbells up and away from your body, extending your arms fully.\nPause for a moment at the top, then slowly lower the dumbbells back to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0645 \u0628\u0625\u0639\u062f\u0627\u062f \u0645\u0642\u0639\u062f \u0645\u0627\u0626\u0644 \u0628\u0632\u0627\u0648\u064a\u0629 45 \u062f\u0631\u062c\u0629.\n\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0627\u0644\u0645\u0642\u0639\u062f \u0645\u0639 \u0648\u062c\u0648\u062f \u062f\u0645\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f\u060c \u0645\u0639 \u0648\u0636\u0639 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u0628\u0639\u0636\u0647\u0645\u0627 \u0627\u0644\u0628\u0639\u0636.\n\u062b\u0628\u0651\u062a \u0642\u062f\u0645\u064a\u0643 \u0628\u0642\u0648\u0629 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0648\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0639\u0644\u0649 \u0627\u0644\u0645\u0642\u0639\u062f.\n\u0627\u0628\u062f\u0623 \u0628\u0627\u0644\u062f\u0645\u0628\u0644 \u0639\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0645\u0639 \u062b\u0646\u064a \u0627\u0644\u0645\u0631\u0641\u0642\u064a\u0646 \u0648\u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u0628\u0639\u0636\u0647\u0645\u0627 \u0627\u0644\u0628\u0639\u0636.\n\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u062f\u0645\u0628\u0644 \u0644\u0623\u0639\u0644\u0649 \u0648\u0628\u0639\u064a\u062f\u064b\u0627 \u0639\u0646 \u062c\u0633\u0645\u0643\u060c \u0645\u0639 \u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0627\u0644\u062f\u0645\u0628\u0644\u0632 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0324","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"pectorals","secondary_muscles":["shoulders","triceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0324-OVLmUuL.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0324-OVLmUuL.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"1fb33aa8-ad26-54de-86d0-1590232b83fc","source_id":"1283","name_en":"dumbbell incline press on exercise ball","name_ar":"\u0627\u0644\u0636\u063a\u0637 \u0628\u0627\u0644\u062f\u0645\u0628\u0644 \u0639\u0644\u0649 \u0643\u0631\u0629 \u0627\u0644\u062a\u0645\u0631\u064a\u0646","match_names":["dumbbell incline press on exercise ball"],"muscle":"chest","equipment":"dumbbell","aliases":["dumbbell incline press on exercise ball"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Sit on an exercise ball with a dumbbell in each hand, palms facing forward.\nSlowly walk your feet forward, rolling your body down the ball until your head, neck, and upper back are supported on the ball.\nHold the dumbbells at shoulder level, elbows bent and pointing out to the sides.\nPress the dumbbells upward, extending your arms fully.\nPause for a moment at the top, then slowly lower the dumbbells back to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0643\u0631\u0629 \u062a\u0645\u0631\u064a\u0646 \u0645\u0639 \u0648\u062c\u0648\u062f \u062f\u0645\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0644\u0644\u0623\u0645\u0627\u0645.\n\u0642\u0645 \u0628\u0627\u0644\u0645\u0634\u064a \u0628\u0628\u0637\u0621 \u0628\u0642\u062f\u0645\u064a\u0643 \u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0627\u0645\u060c \u0648\u062f\u062d\u0631\u062c \u062c\u0633\u0645\u0643 \u0625\u0644\u0649 \u0623\u0633\u0641\u0644 \u0627\u0644\u0643\u0631\u0629 \u062d\u062a\u0649 \u064a\u062a\u0645 \u062f\u0639\u0645 \u0631\u0623\u0633\u0643 \u0648\u0631\u0642\u0628\u062a\u0643 \u0648\u0623\u0639\u0644\u0649 \u0638\u0647\u0631\u0643 \u0639\u0644\u0649 \u0627\u0644\u0643\u0631\u0629.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u062f\u0645\u0628\u0644\u0632 \u0639\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0645\u0639 \u062b\u0646\u064a \u0627\u0644\u0645\u0631\u0641\u0642\u064a\u0646 \u0648\u062a\u0648\u062c\u064a\u0647\u0647\u0645\u0627 \u0625\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646.\n\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u062f\u0645\u0628\u0644\u0632 \u0644\u0623\u0639\u0644\u0649\u060c \u0645\u0639 \u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0627\u0644\u062f\u0645\u0628\u0644\u0632 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1283","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"pectorals","secondary_muscles":["shoulders","triceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1283-bfiHMpI.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1283-bfiHMpI.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"e3a3e08b-5907-5cbb-8f5e-945703f7418a","source_id":"0325","name_en":"dumbbell incline raise","name_ar":"\u0631\u0641\u0639 \u0645\u0646\u062d\u062f\u0631 \u0627\u0644\u062f\u0645\u0628\u0644","match_names":["dumbbell incline raise"],"muscle":"shoulders","equipment":"dumbbell","aliases":["dumbbell incline raise"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Sit on an incline bench with a dumbbell in each hand, resting on your thighs.\nLean back on the bench and raise the dumbbells to shoulder height, palms facing forward.\nKeeping your back against the bench, exhale and raise the dumbbells above your head, fully extending your arms.\nPause for a moment at the top, then inhale and slowly lower the dumbbells back to shoulder height.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0645\u0642\u0639\u062f \u0645\u0627\u0626\u0644 \u0645\u0639 \u0648\u062c\u0648\u062f \u062f\u0645\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f\u060c \u0648\u0627\u0633\u062a\u0631\u064a\u062d \u0639\u0644\u0649 \u0641\u062e\u0630\u064a\u0643.\n\u0627\u0633\u062a\u0644\u0642\u0650 \u0639\u0644\u0649 \u0627\u0644\u0645\u0642\u0639\u062f \u0648\u0627\u0631\u0641\u0639 \u0627\u0644\u062f\u0645\u0628\u0644 \u0625\u0644\u0649 \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0644\u0644\u0623\u0645\u0627\u0645.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0638\u0647\u0631\u0643 \u0639\u0644\u0649 \u0627\u0644\u0645\u0642\u0639\u062f\u060c \u0648\u0642\u0645 \u0628\u0627\u0644\u0632\u0641\u064a\u0631 \u0648\u0627\u0631\u0641\u0639 \u0627\u0644\u062f\u0645\u0628\u0644 \u0641\u0648\u0642 \u0631\u0623\u0633\u0643\u060c \u0648\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u062e\u0630 \u0634\u0647\u064a\u0642\u064b\u0627 \u0648\u0642\u0645 \u0628\u062e\u0641\u0636 \u0627\u0644\u062f\u0645\u0628\u0644\u0632 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0643\u062a\u0641.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0325","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"delts","secondary_muscles":["trapezius","triceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0325-nxW6BkN.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0325-nxW6BkN.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"433a3ab5-9ca1-52ca-8973-cd0c18ba974f","source_id":"0326","name_en":"dumbbell incline rear lateral raise","name_ar":"\u0627\u0644\u062f\u0645\u0628\u0644 \u0645\u0646\u062d\u062f\u0631 \u0627\u0644\u0631\u0641\u0639 \u0627\u0644\u062c\u0627\u0646\u0628\u064a \u0627\u0644\u062e\u0644\u0641\u064a","match_names":["dumbbell incline rear lateral raise"],"muscle":"shoulders","equipment":"dumbbell","aliases":["dumbbell incline rear lateral raise"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Set up an incline bench at a 45-degree angle.\nSit on the bench with your chest against the backrest and hold a dumbbell in each hand.\nExtend your arms straight down with your palms facing each other.\nKeeping a slight bend in your elbows, raise your arms out to the sides until they are parallel to the ground.\nPause for a moment at the top, then slowly lower your arms back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0645 \u0628\u0625\u0639\u062f\u0627\u062f \u0645\u0642\u0639\u062f \u0645\u0627\u0626\u0644 \u0628\u0632\u0627\u0648\u064a\u0629 45 \u062f\u0631\u062c\u0629.\n\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0627\u0644\u0645\u0642\u0639\u062f \u0645\u0639 \u0648\u0636\u0639 \u0635\u062f\u0631\u0643 \u0639\u0644\u0649 \u0645\u0633\u0646\u062f \u0627\u0644\u0638\u0647\u0631 \u0648\u0627\u0645\u0633\u0643 \u0627\u0644\u062f\u0645\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f.\n\u0642\u0645 \u0628\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0625\u0644\u0649 \u0627\u0644\u0623\u0633\u0641\u0644 \u0628\u062d\u064a\u062b \u062a\u0643\u0648\u0646 \u0631\u0627\u062d\u062a\u0627 \u064a\u062f\u064a\u0643 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u0628\u0639\u0636\u0647\u0645\u0627 \u0627\u0644\u0628\u0639\u0636.\n\u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0646\u062d\u0646\u0627\u0621 \u0637\u0641\u064a\u0641 \u0641\u064a \u0645\u0631\u0641\u0642\u064a\u0643\u060c \u0627\u0631\u0641\u0639 \u0630\u0631\u0627\u0639\u064a\u0643 \u0625\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646 \u062d\u062a\u0649 \u064a\u0635\u0628\u062d\u0627 \u0645\u0648\u0627\u0632\u064a\u064a\u0646 \u0644\u0644\u0623\u0631\u0636.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0326","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"delts","secondary_muscles":["traps","rhomboids"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0326-vYk8lqw.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0326-vYk8lqw.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"5287159e-b3c2-56ff-8524-7145397038e7","source_id":"0327","name_en":"dumbbell incline row","name_ar":"\u0635\u0641 \u0645\u0646\u062d\u062f\u0631 \u0627\u0644\u062f\u0645\u0628\u0644","match_names":["dumbbell incline row"],"muscle":"back","equipment":"dumbbell","aliases":["dumbbell incline row"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Set up an incline bench at a 45-degree angle.\nGrab a dumbbell in each hand and sit on the bench with your chest against the incline.\nExtend your arms fully, allowing the dumbbells to hang straight down from your shoulders.\nPull the dumbbells up towards your chest, squeezing your shoulder blades together.\nPause for a moment at the top, then slowly lower the dumbbells back to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0645 \u0628\u0625\u0639\u062f\u0627\u062f \u0645\u0642\u0639\u062f \u0645\u0627\u0626\u0644 \u0628\u0632\u0627\u0648\u064a\u0629 45 \u062f\u0631\u062c\u0629.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u062f\u0645\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f \u0648\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0627\u0644\u0645\u0642\u0639\u062f \u0645\u0639 \u0648\u0636\u0639 \u0635\u062f\u0631\u0643 \u0639\u0644\u0649 \u0627\u0644\u0645\u0646\u062d\u062f\u0631.\n\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644\u060c \u0645\u0645\u0627 \u064a\u0633\u0645\u062d \u0644\u0644\u062f\u0645\u0628\u0644 \u0628\u0627\u0644\u062a\u062f\u0644\u064a \u0645\u0646 \u0643\u062a\u0641\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645.\n\u0627\u0633\u062d\u0628 \u0627\u0644\u062f\u0645\u0628\u0644\u0632 \u0646\u062d\u0648 \u0635\u062f\u0631\u0643\u060c \u0645\u0639 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0644\u0648\u062d\u064a \u0627\u0644\u0643\u062a\u0641 \u0645\u0639\u064b\u0627.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0627\u0644\u062f\u0645\u0628\u0644\u0632 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0327","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"upper back","secondary_muscles":["biceps","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0327-7vG5o25.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0327-7vG5o25.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"6d57f697-b92a-59c0-8fa7-41b3819ebab3","source_id":"0328","name_en":"dumbbell incline shoulder raise","name_ar":"\u0631\u0641\u0639 \u0627\u0644\u0643\u062a\u0641 \u0628\u0627\u0644\u062f\u0645\u0628\u0644","match_names":["dumbbell incline shoulder raise"],"muscle":"serratus_anterior","equipment":"dumbbell","aliases":["dumbbell incline shoulder raise"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing down.\nRest the dumbbells on your thighs and lean back onto the bench.\nUse your thighs to help raise the dumbbells to shoulder height, then rotate your wrists so that your palms are facing forward.\nExhale and slowly raise the dumbbells above your head, keeping a slight bend in your elbows.\nPause for a moment at the top, then inhale and slowly lower the dumbbells back to shoulder height.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0636\u0628\u0637 \u0627\u0644\u0645\u0642\u0639\u062f \u0627\u0644\u0645\u0627\u0626\u0644 \u0628\u0632\u0627\u0648\u064a\u0629 45 \u062f\u0631\u062c\u0629 \u0648\u0627\u062c\u0644\u0633 \u0639\u0644\u064a\u0647 \u0645\u0639 \u0648\u062c\u0648\u062f \u062f\u0645\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0644\u0644\u0623\u0633\u0641\u0644.\n\u0636\u0639 \u0627\u0644\u062f\u0645\u0628\u0644 \u0639\u0644\u0649 \u0641\u062e\u0630\u064a\u0643 \u0648\u0627\u0631\u062c\u0639 \u0625\u0644\u0649 \u0627\u0644\u0645\u0642\u0639\u062f.\n\u0627\u0633\u062a\u062e\u062f\u0645 \u0641\u062e\u0630\u064a\u0643 \u0644\u0644\u0645\u0633\u0627\u0639\u062f\u0629 \u0641\u064a \u0631\u0641\u0639 \u0627\u0644\u062f\u0645\u0628\u0644 \u0625\u0644\u0649 \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0643\u062a\u0641\u060c \u062b\u0645 \u0642\u0645 \u0628\u062a\u062f\u0648\u064a\u0631 \u0645\u0639\u0635\u0645\u064a\u0643 \u0628\u062d\u064a\u062b \u062a\u0643\u0648\u0646 \u0631\u0627\u062d\u0629 \u064a\u062f\u0643 \u0645\u062a\u062c\u0647\u0629 \u0644\u0644\u0623\u0645\u0627\u0645.\n\u0642\u0645 \u0628\u0627\u0644\u0632\u0641\u064a\u0631 \u0648\u0627\u0631\u0641\u0639 \u0627\u0644\u062f\u0645\u0628\u0644 \u0628\u0628\u0637\u0621 \u0641\u0648\u0642 \u0631\u0623\u0633\u0643\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0646\u062d\u0646\u0627\u0621 \u0637\u0641\u064a\u0641 \u0641\u064a \u0645\u0631\u0641\u0642\u064a\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u062e\u0630 \u0634\u0647\u064a\u0642\u064b\u0627 \u0648\u0642\u0645 \u0628\u062e\u0641\u0636 \u0627\u0644\u062f\u0645\u0628\u0644\u0632 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0643\u062a\u0641.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0328","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"serratus anterior","secondary_muscles":["deltoids","trapezius"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0328-6e2DcYX.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0328-6e2DcYX.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"bdedf0cb-5daf-55d6-8469-eeef05fc6196","source_id":"0329","name_en":"dumbbell incline shrug","name_ar":"\u0627\u0644\u062f\u0645\u0628\u0644 \u0627\u0646\u062d\u062f\u0631 \u062a\u062a\u063a\u0627\u0636\u0649","match_names":["dumbbell incline shrug"],"muscle":"back","equipment":"dumbbell","aliases":["dumbbell incline shrug"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand.\nPlace your feet flat on the ground and let your arms hang straight down with your palms facing your body.\nKeeping your arms straight, shrug your shoulders up towards your ears as high as possible.\nHold the contraction for a moment, then slowly lower your shoulders back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0636\u0628\u0637 \u0627\u0644\u0645\u0642\u0639\u062f \u0627\u0644\u0645\u0627\u0626\u0644 \u0628\u0632\u0627\u0648\u064a\u0629 45 \u062f\u0631\u062c\u0629 \u0648\u0627\u062c\u0644\u0633 \u0639\u0644\u064a\u0647 \u0645\u0639 \u0648\u062c\u0648\u062f \u062f\u0645\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f.\n\u0636\u0639 \u0642\u062f\u0645\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u0637\u062d \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636\u060c \u0648\u0627\u062a\u0631\u0643 \u0630\u0631\u0627\u0639\u064a\u0643 \u062a\u062a\u062f\u0644\u0649 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0644\u0644\u0623\u0633\u0641\u0644 \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0644\u062c\u0633\u0645\u0643.\n\u0623\u0628\u0642\u0650 \u0630\u0631\u0627\u0639\u064a\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u062a\u064a\u0646\u060c \u0648\u0627\u0631\u0641\u0639 \u0643\u062a\u0641\u064a\u0643 \u0646\u062d\u0648 \u0623\u0630\u0646\u064a\u0643 \u0628\u0623\u0639\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0645\u0645\u0643\u0646.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u0627\u0646\u0642\u0628\u0627\u0636 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0627\u062e\u0641\u0636 \u0643\u062a\u0641\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0329","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"traps","secondary_muscles":["shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0329-JymLInS.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0329-JymLInS.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"22ef2389-d8ea-5a38-8298-5dc94f2ec8d5","source_id":"3542","name_en":"dumbbell incline t-raise","name_ar":"\u0627\u0644\u062f\u0645\u0628\u0644 \u0645\u0646\u062d\u062f\u0631 T-\u0631\u0641\u0639","match_names":["dumbbell incline t-raise"],"muscle":"shoulders","equipment":"dumbbell","aliases":["dumbbell incline t-raise"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing inwards.\nLean forward and let your arms hang straight down, perpendicular to the floor.\nKeeping your arms straight, raise them out to the sides until they are parallel to the floor, forming a ''T'' shape with your body.\nPause for a moment at the top, then slowly lower your arms back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0636\u0628\u0637 \u0627\u0644\u0645\u0642\u0639\u062f \u0627\u0644\u0645\u0627\u0626\u0644 \u0628\u0632\u0627\u0648\u064a\u0629 45 \u062f\u0631\u062c\u0629 \u0648\u0627\u062c\u0644\u0633 \u0639\u0644\u064a\u0647 \u0645\u0639 \u0648\u062c\u0648\u062f \u062f\u0645\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0625\u0644\u0649 \u0627\u0644\u062f\u0627\u062e\u0644.\n\u0627\u0646\u062d\u0646\u0650 \u0644\u0644\u0623\u0645\u0627\u0645 \u0648\u0627\u062a\u0631\u0643 \u0630\u0631\u0627\u0639\u064a\u0643 \u062a\u062a\u062f\u0644\u0649 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0644\u0644\u0623\u0633\u0641\u0644\u060c \u0628\u0634\u0643\u0644 \u0639\u0645\u0648\u062f\u064a \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0623\u0628\u0642\u0650 \u0630\u0631\u0627\u0639\u064a\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u062a\u064a\u0646\u060c \u0648\u0627\u0631\u0641\u0639\u0647\u0645\u0627 \u0625\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646 \u062d\u062a\u0649 \u064a\u0635\u0628\u062d\u0627 \u0645\u0648\u0627\u0632\u064a\u064a\u0646 \u0644\u0644\u0623\u0631\u0636\u060c \u0644\u062a\u0634\u0643\u0644 \u0634\u0643\u0644 \u062d\u0631\u0641 \"T\" \u0628\u062c\u0633\u0645\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3542","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"delts","secondary_muscles":["traps","rhomboids"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3542-jgbvVJ0.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3542-jgbvVJ0.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"793116e4-5159-5cd5-8ba2-544bbe55116a","source_id":"0330","name_en":"dumbbell incline triceps extension","name_ar":"\u062a\u0645\u062f\u064a\u062f \u0627\u0644\u0639\u0636\u0644\u0629 \u062b\u0644\u0627\u062b\u064a\u0629 \u0627\u0644\u0631\u0624\u0648\u0633 \u0628\u0627\u0644\u062f\u0645\u0628\u0644","match_names":["dumbbell incline triceps extension"],"muscle":"triceps","equipment":"dumbbell","aliases":["dumbbell incline triceps extension"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Sit on an incline bench with a dumbbell in each hand, palms facing inwards.\nExtend your arms fully overhead, keeping your elbows close to your head.\nLower the dumbbells behind your head by bending your elbows, keeping your upper arms stationary.\nPause for a moment, then raise the dumbbells back to the starting position by extending your arms.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0645\u0642\u0639\u062f \u0645\u0627\u0626\u0644 \u0645\u0639 \u0648\u062c\u0648\u062f \u062f\u0645\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0646\u062d\u0648 \u0627\u0644\u062f\u0627\u062e\u0644.\n\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u0625\u0644\u0649 \u0623\u0639\u0644\u0649\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0645\u0631\u0641\u0642\u064a\u0643 \u0642\u0631\u064a\u0628\u064a\u0646 \u0645\u0646 \u0631\u0623\u0633\u0643.\n\u0627\u062e\u0641\u0636 \u0627\u0644\u062f\u0645\u0628\u0644\u0632 \u062e\u0644\u0641 \u0631\u0623\u0633\u0643 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u062b\u0628\u0627\u062a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0630\u0631\u0627\u0639\u064a\u0643.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0627\u0631\u0641\u0639 \u0627\u0644\u062f\u0645\u0628\u0644 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629 \u0639\u0646 \u0637\u0631\u064a\u0642 \u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0330","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"triceps","secondary_muscles":["shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0330-OVIKwsd.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0330-OVIKwsd.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"0704964c-577c-5697-8f33-3859c8c9b8e1","source_id":"0331","name_en":"dumbbell incline twisted flyes","name_ar":"\u0627\u0644\u062f\u0645\u0628\u0644 \u0627\u0644\u0645\u0646\u062d\u062f\u0631 \u0627\u0644\u0630\u0628\u0627\u0628 \u0627\u0644\u0645\u0644\u062a\u0648\u064a\u0629","match_names":["dumbbell incline twisted flyes"],"muscle":"chest","equipment":"dumbbell","aliases":["dumbbell incline twisted flyes"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing each other.\nLie back on the bench and press the dumbbells up to the starting position, directly above your chest, with your arms extended.\nLower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.\nAs you lower the dumbbells, rotate your wrists so that your palms face forward at the bottom of the movement.\nReverse the motion and bring the dumbbells back up to the starting position, squeezing your chest muscles together at the top.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0636\u0628\u0637 \u0627\u0644\u0645\u0642\u0639\u062f \u0627\u0644\u0645\u0627\u0626\u0644 \u0628\u0632\u0627\u0648\u064a\u0629 45 \u062f\u0631\u062c\u0629 \u0648\u0627\u062c\u0644\u0633 \u0639\u0644\u064a\u0647 \u0645\u0639 \u0648\u062c\u0648\u062f \u062f\u0645\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f\u060c \u0645\u0639 \u0648\u0636\u0639 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u0628\u0639\u0636\u0647\u0645\u0627 \u0627\u0644\u0628\u0639\u0636.\n\u0627\u0633\u062a\u0644\u0642\u064a \u0639\u0644\u0649 \u0627\u0644\u0645\u0642\u0639\u062f \u0648\u0627\u0636\u063a\u0637\u064a \u0628\u0627\u0644\u062f\u0645\u0628\u0644\u0632 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629\u060c \u0645\u0628\u0627\u0634\u0631\u0629 \u0641\u0648\u0642 \u0635\u062f\u0631\u0643\u060c \u0645\u0639 \u062a\u0645\u062f\u064a\u062f \u0630\u0631\u0627\u0639\u064a\u0643.\n\u0623\u0646\u0632\u0644 \u0627\u0644\u062f\u0645\u0628\u0644\u0632 \u0625\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646 \u0639\u0644\u0649 \u0634\u0643\u0644 \u0642\u0648\u0633 \u0648\u0627\u0633\u0639 \u062d\u062a\u0649 \u062a\u0634\u0639\u0631 \u0628\u062a\u0645\u062f\u062f \u0641\u064a \u0635\u062f\u0631\u0643.\n\u0623\u062b\u0646\u0627\u0621 \u0642\u064a\u0627\u0645\u0643 \u0628\u062e\u0641\u0636 \u0627\u0644\u062f\u0645\u0628\u0644\u060c \u0642\u0645 \u0628\u062a\u062f\u0648\u064a\u0631 \u0645\u0639\u0635\u0645\u064a\u0643 \u0628\u062d\u064a\u062b \u062a\u0643\u0648\u0646 \u0631\u0627\u062d\u0629 \u064a\u062f\u0643 \u0645\u062a\u062c\u0647\u0629 \u0644\u0644\u0623\u0645\u0627\u0645 \u0641\u064a \u0623\u0633\u0641\u0644 \u0627\u0644\u062d\u0631\u0643\u0629.\n\u0627\u0639\u0643\u0633\u064a \u0627\u0644\u062d\u0631\u0643\u0629 \u0648\u0623\u0639\u064a\u062f\u064a \u0627\u0644\u062f\u0645\u0628\u0644\u0632 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629\u060c \u0645\u0639 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0639\u0636\u0644\u0627\u062a \u0627\u0644\u0635\u062f\u0631 \u0645\u0639\u064b\u0627 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0331","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"pectorals","secondary_muscles":["shoulders","triceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0331-1PLE8e9.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0331-1PLE8e9.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"1452fdf1-935b-5d96-8e7d-39ba72e8df94","source_id":"1733","name_en":"dumbbell incline two arm extension","name_ar":"\u0627\u0644\u062f\u0645\u0628\u0644 \u064a\u0646\u062d\u062f\u0631 \u0628\u0630\u0631\u0627\u0639\u064a\u0646 \u0645\u0645\u062a\u062f\u062a\u064a\u0646","match_names":["dumbbell incline two arm extension"],"muscle":"triceps","equipment":"dumbbell","aliases":["dumbbell incline two arm extension"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Sit on an incline bench with a dumbbell in each hand, resting on your thighs.\nSlowly lie back on the bench, keeping the dumbbells close to your chest.\nOnce you are fully lying down, extend your arms straight up towards the ceiling, keeping your elbows slightly bent.\nPause for a moment at the top, then slowly lower the dumbbells back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0645\u0642\u0639\u062f \u0645\u0627\u0626\u0644 \u0645\u0639 \u0648\u062c\u0648\u062f \u062f\u0645\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f\u060c \u0648\u0627\u0633\u062a\u0631\u064a\u062d \u0639\u0644\u0649 \u0641\u062e\u0630\u064a\u0643.\n\u0627\u0633\u062a\u0644\u0642\u064a \u0628\u0628\u0637\u0621 \u0639\u0644\u0649 \u0627\u0644\u0645\u0642\u0639\u062f\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0627\u0644\u062f\u0645\u0628\u0644\u0632 \u0628\u0627\u0644\u0642\u0631\u0628 \u0645\u0646 \u0635\u062f\u0631\u0643.\n\u0628\u0645\u062c\u0631\u062f \u0627\u0644\u0627\u0633\u062a\u0644\u0642\u0627\u0621 \u0628\u0634\u0643\u0644 \u0643\u0627\u0645\u0644\u060c \u0642\u0645 \u0628\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0646\u062d\u0648 \u0627\u0644\u0633\u0642\u0641\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643 \u0642\u0644\u064a\u0644\u0627\u064b.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0627\u0644\u062f\u0645\u0628\u0644\u0632 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1733","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"triceps","secondary_muscles":["shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1733-U7D9Fx3.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1733-U7D9Fx3.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"e9c36440-69ff-57a2-82b7-8cd0e3dce4b0","source_id":"3541","name_en":"dumbbell incline y-raise","name_ar":"\u0627\u0644\u062f\u0645\u0628\u0644 \u0627\u0646\u062d\u062f\u0631 Y-\u0631\u0641\u0639","match_names":["dumbbell incline y-raise"],"muscle":"back","equipment":"dumbbell","aliases":["dumbbell incline y-raise"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing inwards.\nLean forward slightly and let your arms hang straight down, keeping a slight bend in your elbows.\nRaise your arms out to the sides and up in a Y shape until they are parallel to the ground.\nPause for a moment at the top, then slowly lower your arms back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0636\u0628\u0637 \u0627\u0644\u0645\u0642\u0639\u062f \u0627\u0644\u0645\u0627\u0626\u0644 \u0628\u0632\u0627\u0648\u064a\u0629 45 \u062f\u0631\u062c\u0629 \u0648\u0627\u062c\u0644\u0633 \u0639\u0644\u064a\u0647 \u0645\u0639 \u0648\u062c\u0648\u062f \u062f\u0645\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0625\u0644\u0649 \u0627\u0644\u062f\u0627\u062e\u0644.\n\u0627\u0646\u062d\u0646\u0650 \u0644\u0644\u0623\u0645\u0627\u0645 \u0642\u0644\u064a\u0644\u064b\u0627 \u0648\u0627\u062a\u0631\u0643 \u0630\u0631\u0627\u0639\u064a\u0643 \u062a\u062a\u062f\u0644\u0649 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0644\u0644\u0623\u0633\u0641\u0644\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0646\u062d\u0646\u0627\u0621 \u0637\u0641\u064a\u0641 \u0641\u064a \u0645\u0631\u0641\u0642\u064a\u0643.\n\u0627\u0631\u0641\u0639\u064a \u0630\u0631\u0627\u0639\u064a\u0643 \u0625\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646 \u0648\u0625\u0644\u0649 \u0627\u0644\u0623\u0639\u0644\u0649 \u0639\u0644\u0649 \u0634\u0643\u0644 \u062d\u0631\u0641 Y \u062d\u062a\u0649 \u064a\u0635\u0628\u062d\u0627 \u0645\u0648\u0627\u0632\u064a\u064a\u0646 \u0644\u0644\u0623\u0631\u0636.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3541","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"upper back","secondary_muscles":["shoulders","rear deltoids"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3541-PbzNu7c.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3541-PbzNu7c.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"556494e3-f1bd-5546-89fa-0f51c505a2f0","source_id":"0332","name_en":"dumbbell iron cross","name_ar":"\u0627\u0644\u0635\u0644\u064a\u0628 \u0627\u0644\u062d\u062f\u064a\u062f\u064a \u0627\u0644\u062f\u0645\u0628\u0644","match_names":["dumbbell iron cross"],"muscle":"shoulders","equipment":"dumbbell","aliases":["dumbbell iron cross"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.\nRaise your arms out to the sides until they are parallel to the ground, forming a T shape with your body.\nPause for a moment, then slowly lower your arms back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0648\u0623\u0645\u0633\u0643 \u0627\u0644\u062f\u0645\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f \u0639\u0644\u0649 \u062c\u0627\u0646\u0628\u064a\u0643.\n\u0627\u0631\u0641\u0639\u064a \u0630\u0631\u0627\u0639\u064a\u0643 \u0625\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646 \u062d\u062a\u0649 \u064a\u0635\u0628\u062d\u0627 \u0645\u0648\u0627\u0632\u064a\u064a\u0646 \u0644\u0644\u0623\u0631\u0636\u060c \u0644\u064a\u0634\u0643\u0644 \u062c\u0633\u0645\u0643 \u0634\u0643\u0644 \u062d\u0631\u0641 T.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0332","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"delts","secondary_muscles":["triceps","chest"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0332-cALkHHX.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0332-cALkHHX.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}}]'::jsonb)
AS r(id uuid,source_id text,name_en text,name_ar text,match_names jsonb,muscle text,equipment text,aliases jsonb,logging_mode text,load_convention text,guidance jsonb);
DO $$ BEGIN
 IF EXISTS (SELECT 1 FROM catalogue_input r WHERE (SELECT count(*) FROM public.exercises e WHERE
   (e.guidance->'text_source'->>'repository'='hasaneyldrm/exercises-dataset' AND e.guidance->'text_source'->>'exercise_id'=r.source_id)
   OR (e.guidance->'text_source' IS NULL AND lower(trim(e.name_en)) IN (SELECT lower(value) FROM jsonb_array_elements_text(r.match_names)) AND e.equipment=r.equipment))>1)
 THEN RAISE EXCEPTION 'Ambiguous catalogue match; review before importing'; END IF;
END $$;
INSERT INTO public.exercises(id,name_en,name_ar,muscle,equipment,equipment_tags,aliases,logging_mode,load_convention,guidance,editorial_status)
SELECT coalesce((SELECT e.id FROM public.exercises e WHERE
  (e.guidance->'text_source'->>'repository'='hasaneyldrm/exercises-dataset' AND e.guidance->'text_source'->>'exercise_id'=r.source_id)
  OR (e.guidance->'text_source' IS NULL AND lower(trim(e.name_en)) IN (SELECT lower(value) FROM jsonb_array_elements_text(r.match_names)) AND e.equipment=r.equipment)),r.id),
 r.name_en,r.name_ar,r.muscle,r.equipment,ARRAY[r.equipment],ARRAY(SELECT jsonb_array_elements_text(r.aliases)),r.logging_mode,r.load_convention,r.guidance,'needs_review'
FROM catalogue_input r
ON CONFLICT(id) DO UPDATE SET
 name_ar=coalesce(nullif(public.exercises.name_ar,''),EXCLUDED.name_ar),
 aliases=ARRAY(SELECT DISTINCT value FROM unnest(public.exercises.aliases || EXCLUDED.aliases) value ORDER BY value),
 guidance=EXCLUDED.guidance || public.exercises.guidance
WHERE public.exercises.editorial_status<>'reviewed'
 AND (public.exercises.guidance->'text_source' IS NULL OR
  (public.exercises.guidance->'text_source'->>'repository'='hasaneyldrm/exercises-dataset' AND public.exercises.guidance->'text_source'->>'exercise_id'=EXCLUDED.guidance->'text_source'->>'exercise_id'));
COMMIT;
